 public static void main(String[] args)throws Exception{Console con=System.console();if(con==null)throw new IllegalStateException("Chạy trong CMD/terminal có console");String name=con.readLine("Tên đăng nhập admin: ").trim();if(!name.matches("[A-Za-z0-9_.-]{3,80}"))throw new IllegalArgumentException("Tên không hợp lệ");char[] pw=con.readPassword("Mật khẩu (ít nhất 10 ký tự): ");char[] repeat=con.readPassword("Nhập lại: ");try{if(!Arrays.equals(pw,repeat))throw new IllegalArgumentException("Mật khẩu không khớp");String hash=TaiKhoanDAO.bamMatKhau(pw);try(Connection c=database.getConnection()){c.setAutoCommit(false);try{try(PreparedStatement p=c.prepareStatement("SELECT hoten FROM `user` WHERE VaiTro='ADMIN' FOR UPDATE");ResultSet r=p.executeQuery()){if(r.next())throw new IllegalStateException("Đã có ADMIN; tạo tài khoản khác trong giao diện");}try(PreparedStatement p=c.prepareStatement("INSERT INTO `user`(hoten,mk,TenNV,VaiTro) VALUES(?,?,?,'ADMIN')")){p.setString(1,name);p.setString(2,hash);p.setString(3,name);p.executeUpdate();}c.commit();}catch(Exception e){c.rollback();throw e;}}System.out.println("Đã tạo admin: "+name);}finally{Arrays.fill(pw,'\0');Arrays.fill(repeat,'\0');}}
